import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";

function App() {
  const [questions, setQuestions] = useState([]);
  const [selectedQuestions, setSelectedQuestions] = useState([null, null, null]);
  const [answers, setAnswers] = useState(["", "", ""]);

  // Fetch questions from backend
  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        const res = await axios.get("http://localhost:3001/questions");
        setQuestions(res.data);
      } catch (err) {
        console.error("Error fetching questions:", err);
      }
    };
    fetchQuestions();
  }, []);

  // Update selected question in a card
  const handleSelect = (index, questionId) => {
    const newSelected = [...selectedQuestions];
    newSelected[index] = parseInt(questionId);
    setSelectedQuestions(newSelected);
  };

  // Update answer in a card
  const handleAnswerChange = (index, value) => {
    const newAnswers = [...answers];
    newAnswers[index] = value;
    setAnswers(newAnswers);
  };

  // Submit all responses to backend
  const handleSubmit = async () => {
    // Validate
    if (selectedQuestions.includes(null) || answers.includes("")) {
      alert("Please select all questions and enter all answers.");
      return;
    }

    const payload = selectedQuestions.map((qid, i) => ({
      questionId: qid,
      answer: answers[i],
    }));

    try {
      const res = await axios.post("http://localhost:3001/responses", payload);
      alert("Responses saved successfully!");
      console.log(res.data);

      // Reset form
      setSelectedQuestions([null, null, null]);
      setAnswers(["", "", ""]);
    } catch (err) {
      console.error(err);
      alert("Failed to save responses.");
    }
  };

  return (
    <div style={{ padding: "20px", maxWidth: "500px", margin: "0 auto" }}>
      <h2>Security Questions</h2>

      {[0, 1, 2].map((i) => (
        <QuestionCard
          key={i}
          index={i}
          questions={questions.filter(
            (q) => !selectedQuestions.includes(q.id) || selectedQuestions[i] === q.id
          )}
          selectedQuestionId={selectedQuestions[i]}
          handleSelect={handleSelect}
          handleAnswerChange={handleAnswerChange}
          answers={answers}
        />
      ))}

      <button onClick={handleSubmit} style={{ marginTop: "20px", padding: "10px 20px" }}>
        Submit
      </button>
    </div>
  );
}

export default App;
